import {
  Button,
  DateInput,
  DateRangePicker as AriaDateRangePicker,
  DateSegment,
  FieldError,
  Group,
  Label,
  Text,
} from "react-aria-components";
import type {
  DateRangePickerProps as AriaDateRangePickerProps,
  DateValue,
  ValidationResult,
} from "react-aria-components";
import { ChevronDown } from "./icons";
import type { ReactNode, Ref } from "react";
import { RangeCalendar } from "./RangeCalendar";
import { PopoverContent } from "./Popover";
import { roleSize, type ControlSize } from "./controlSize";
import "./DateRangePicker.css";

/** No `x-small` or `small`: a segment in a control of 32px or less is narrower than the 24px pointer target WCAG 2.5.8
    asks for, and flush segments cannot use its spacing exception. */
type DateRangePickerSize = Exclude<ControlSize, "x-small" | "small">;

export interface DateRangePickerProps
  extends Omit<AriaDateRangePickerProps<DateValue>, "className" | "children"> {
  /**
   * Size axis for the field wrapper.
   *
   * @default "medium"
   */
  size?: DateRangePickerSize;
  /** Field label. */
  label?: string;
  /**
   * A `ContextualHelp` shown after the label, for a note the reader opens when they need it rather
   * than a `description` that is always on screen.
   */
  contextualHelp?: ReactNode;
  /** Helper text below the field. */
  description?: string;
  /** Message shown when validation fails. */
  errorMessage?: string | ((v: ValidationResult) => string);
  /** Additional class. sd-date-range-picker is always preserved. */
  className?: string;
  /** Forwarded to the root date range picker DOM node. */
  ref?: Ref<HTMLDivElement>;
}

export function DateRangePicker({
  size = "medium",
  label,
  contextualHelp,
  description,
  errorMessage,
  className,
  ref,
  ...props
}: DateRangePickerProps) {
  return (
    <AriaDateRangePicker
      {...props}
      ref={ref}
      className={className ? `sd-date-range-picker ${className}` : "sd-date-range-picker"}
    >
      {contextualHelp ? (
        <div className="sd-date-range-picker__label-group">
          {label && <Label className={`sd-date-range-picker__label sd-type-label-${roleSize(size)}`}>{label}</Label>}
          {contextualHelp}
        </div>
      ) : (
        label && <Label className={`sd-date-range-picker__label sd-type-label-${roleSize(size)}`}>{label}</Label>
      )}
      <Group data-size={size} className={`sd-date-range-picker__group sd-type-body-${roleSize(size)}`}>
        <DateInput slot="start" className="sd-date-range-picker__input">
          {(segment) => (
            <DateSegment segment={segment} className="sd-date-range-picker__segment" />
          )}
        </DateInput>
        <span aria-hidden="true" className="sd-date-range-picker__dash">
          –
        </span>
        <DateInput slot="end" className="sd-date-range-picker__input">
          {(segment) => (
            <DateSegment segment={segment} className="sd-date-range-picker__segment" />
          )}
        </DateInput>
        <Button data-size={size} className="sd-date-range-picker__trigger">
          <ChevronDown aria-hidden size="1em" />
        </Button>
      </Group>
      {description && (
        <Text
          slot="description"
          className={`sd-date-range-picker__description sd-type-caption-${roleSize(size)}`}
        >
          {description}
        </Text>
      )}
      <FieldError className={`sd-date-range-picker__error sd-type-caption-${roleSize(size)}`}>
        {errorMessage}
      </FieldError>
      {/* Registry dependency: DateRangePicker reuses the local RangeCalendar + Popover components. */}
      <PopoverContent>
        <RangeCalendar />
      </PopoverContent>
    </AriaDateRangePicker>
  );
}

.sd-date-range-picker {
  --sd-date-range-picker-group-background-current: var(--sd-date-range-picker-group-background);
  display: flex;
  flex-direction: column;
  gap: var(--sd-date-range-picker-gap);
}
.sd-date-range-picker[data-readonly] {
  --sd-date-range-picker-group-background-current: var(--sd-date-range-picker-group-background-readonly);
}

/* label-group — present only with `contextualHelp`: the label and its help trigger share one row. */
.sd-date-range-picker__label-group {
  display: flex;
  align-items: center;
  gap: var(--sd-date-range-picker-label-group-gap);
}

.sd-date-range-picker__label {
  padding-inline: var(--sd-date-range-picker-text-padding-inline);
  color: var(--sd-date-range-picker-label-foreground);
}

/* GRID, not flex — the same construction ComboBox and NumberField already use, and for a reason the
   trigger below depends on: that chip is a square sized by the row, which needs `aspect-ratio` to
   transfer the stretched height into the width. In a ROW FLEX container the main size (width) is
   resolved before the cross size is definite, so the transfer never happens and the chip collapses to
   its icon (measured 16×30). In grid the row height is definite first, so it does (30×30).
   Tracks: start date hugs, the dash hugs, the end date takes the slack, the chip hugs — so the chip
   stays pinned to the inline end. */
.sd-date-range-picker__group {
  --sd-date-range-picker-group-radius-current: var(--sd-date-range-picker-group-radius-medium);
  display: grid;
  grid-template-columns: auto auto 1fr auto;
  align-items: center;
  width: 100%;
  padding-block: var(--sd-date-range-picker-group-padding-block);
  background: var(--sd-date-range-picker-group-background-current);
  color: var(--sd-date-range-picker-group-foreground);
  border: var(--sd-date-range-picker-group-border-width) solid var(--sd-date-range-picker-group-border);
  border-radius: var(--sd-date-range-picker-group-radius-current);
  corner-shape: superellipse(var(--sd-radius-curve));
  transition:
    border-color var(--sd-duration-moderate) var(--sd-easing-standard),
    box-shadow var(--sd-duration-moderate) var(--sd-easing-standard);
  padding-inline-end: 0;
}

.sd-date-range-picker__group[data-size="medium"] {
  --sd-date-range-picker-group-radius-current: var(--sd-date-range-picker-group-radius-medium);
  min-height: var(--sd-date-range-picker-group-height-medium);
  padding-inline-start: var(--sd-date-range-picker-group-padding-inline-medium);
  --sd-date-range-picker-segment-padding-inline-current: var(--sd-date-range-picker-segment-padding-inline-medium);
  --sd-date-range-picker-trigger-icon-size-current: var(--sd-date-range-picker-trigger-icon-size-medium);
}

.sd-date-range-picker__group[data-size="large"] {
  --sd-date-range-picker-group-radius-current: var(--sd-date-range-picker-group-radius-large);
  min-height: var(--sd-date-range-picker-group-height-large);
  padding-inline-start: var(--sd-date-range-picker-group-padding-inline-large);
  --sd-date-range-picker-segment-padding-inline-current: var(--sd-date-range-picker-segment-padding-inline-large);
  --sd-date-range-picker-trigger-icon-size-current: var(--sd-date-range-picker-trigger-icon-size-large);
}
.sd-date-range-picker__group[data-size="x-large"] {
  --sd-date-range-picker-group-radius-current: var(--sd-date-range-picker-group-radius-x-large);
  min-height: var(--sd-date-range-picker-group-height-x-large);
  padding-inline-start: var(--sd-date-range-picker-group-padding-inline-x-large);
  --sd-date-range-picker-segment-padding-inline-current: var(--sd-date-range-picker-segment-padding-inline-x-large);
  --sd-date-range-picker-trigger-icon-size-current: var(--sd-date-range-picker-trigger-icon-size-x-large);
}

.sd-date-range-picker__group[data-hovered] {
  border-color: var(--sd-date-range-picker-group-border-hover);
}

.sd-date-range-picker__group[data-focus-within] {
  border-color: var(--sd-date-range-picker-group-border-focus);
  box-shadow: 0 0 0 var(--sd-state-focus-ring-width) color-mix(in srgb, var(--sd-state-focus-ring) calc(var(--sd-state-focus-ring-opacity) * 100%), transparent);
  outline: var(--sd-state-focus-ring-width) solid transparent;
}

.sd-date-range-picker__group[data-invalid] {
  border-color: var(--sd-date-range-picker-group-border-invalid);
}
.sd-date-range-picker__group[data-invalid][data-focus-within] {
  box-shadow: 0 0 0 var(--sd-state-focus-ring-width) color-mix(in srgb, var(--sd-date-range-picker-group-border-invalid) calc(var(--sd-state-focus-ring-opacity) * 100%), transparent);
  outline: var(--sd-state-focus-ring-width) solid transparent;
}

.sd-date-range-picker__group[data-disabled] {
  opacity: var(--sd-state-disabled);
  cursor: not-allowed;
}

.sd-date-range-picker__input {
  display: flex;
  align-items: center;
  align-self: stretch;
  min-width: 0;
  padding-block: var(--sd-date-range-picker-input-padding-block);
  outline: none;
}

/* The two date inputs hug so "start – end" reads as one compact value; the end input
   then fills the remaining width, pushing the trigger to the right edge — the same
   "the filling input positions the trigger" mechanism as DatePicker's single input.
   Targeted by React Aria's rendered slot attribute (same-element, contract §6.2). */
.sd-date-range-picker__input[slot="end"] {
  flex: 1;
}

.sd-date-range-picker__segment {
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: var(--sd-date-range-picker-segment-radius);
  corner-shape: superellipse(var(--sd-radius-curve));
  color: var(--sd-date-range-picker-segment-foreground);
  outline: none;
}

/* Editable segments (month/day/year/…) fill the input height for a control-height tap
   target (WCAG 2.5.8) + a full-height focus chip; literal separators ("/") stay compact. */
.sd-date-range-picker__segment:not([data-type="literal"]) {
  align-self: stretch;
  padding-inline: var(--sd-date-range-picker-segment-padding-inline-current);
}

.sd-date-range-picker__segment[data-placeholder] {
  color: var(--sd-date-range-picker-segment-foreground-placeholder);
}

.sd-date-range-picker__segment[data-focused] {
  background: var(--sd-date-range-picker-segment-background-focus);
  color: var(--sd-date-range-picker-segment-foreground-focus);
}

.sd-date-range-picker__dash {
  margin-inline: var(--sd-date-range-picker-dash-margin-inline);
  color: var(--sd-date-range-picker-dash-foreground);
}

.sd-date-range-picker__trigger {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  font-size: var(--sd-date-range-picker-trigger-icon-size-current);
  /* Resting chip, sized BY the field — it never restates the field's own height. `stretch` takes the
     group's content row (control-height minus its border and block padding) and `aspect-ratio` squares
     it, so the group's `padding-block` IS the chip's block inset and the margin below supplies the
     inline one. Same construction as ComboBox's trigger and NumberField's stepper — neither declares a
     size either.
     A literal `height: control-height` here is the bug this replaces: that is the FULL field height
     applied to a chip INSIDE the field, so the group grew to 58 against its own 40 floor (+18 at every
     size, measured) and the inset came out 9 block / 5 inline instead of uniform. */
  align-self: stretch;
  /* Inline end only — the group zeroes its `padding-inline-end` so this chip can own that edge; the
     block edges already come from the group's `padding-block`. */
  color: var(--sd-date-range-picker-trigger-foreground);
  border: var(--sd-date-range-picker-trigger-border-width) solid var(--sd-date-range-picker-trigger-border);
  cursor: pointer;
  position: relative;
  /* Same structure as Figma: the button is a square hit area the row's height, and the visible chip
     sits inside it. A chip that IS the button (margin + aspect-ratio) has its width fixed first by
     the glyph's intrinsic width and turns into a tall pill. The width is pinned to the row height
     and `::before` draws the chip, so the hit area is 40 and needs no WCAG 2.5.8 helper box. */
  padding: var(--sd-date-range-picker-trigger-overlay-inset);
  background: none;
  /* Inline-end inset + radius — see the matching rule in DatePicker.css for the full reasoning
     (the chip was flush to the field border and drew square against a rounded Figma master, and
     `--sd-date-range-picker-trigger-radius` had zero references). */
  margin-inline-end: var(--sd-date-range-picker-trigger-overlay-inset);
  border-radius: var(--sd-date-range-picker-trigger-radius);
  corner-shape: superellipse(var(--sd-radius-curve));
  outline: none;
}

/* WCAG 2.2 (2.5.8): guarantee a 24px min pointer target. The chip is sized by the field row, so at
   size=small it is 22 — under the minimum. Transparent overlay, so the painted chip is unchanged;
   inert at medium/large where the chip is already 30/38. Same idiom as Checkbox/Radio/Switch. */
/* Square by construction — and this family subtracts the group's BLOCK PADDING too.
   ComboBox/NumberField groups have none, so their content row is height − 2×border; the
   date family adds `padding-block`, so the same formula would leave it 38×30. The width must equal
   whatever the row actually stretches the chip to: the chip's height is the group's content row
   because the grid stretches it, and `aspect-ratio: 1` cannot follow, since a grid sizes the `auto`
   column from the glyph's intrinsic width FIRST and only then makes the height definite. */
.sd-date-range-picker__trigger[data-size="medium"] {
  width: calc(
    var(--sd-date-range-picker-group-height-medium) - 2 * var(--sd-date-range-picker-group-border-width) -
    2 * var(--sd-date-range-picker-group-padding-block)
  );
}
.sd-date-range-picker__trigger[data-size="large"] {
  width: calc(
    var(--sd-date-range-picker-group-height-large) - 2 * var(--sd-date-range-picker-group-border-width) -
    2 * var(--sd-date-range-picker-group-padding-block)
  );
}
.sd-date-range-picker__trigger[data-size="x-large"] {
  width: calc(
    var(--sd-date-range-picker-group-height-x-large) - 2 * var(--sd-date-range-picker-group-border-width) -
    2 * var(--sd-date-range-picker-group-padding-block)
  );
}
.sd-date-range-picker__trigger::before {
  content: "";
  position: absolute;
  top: 50%;
  left: 50%;
  translate: -50% -50%;
  min-width: var(--sd-date-range-picker-trigger-touch-target-size);
  min-height: var(--sd-date-range-picker-trigger-touch-target-size);
}
/* Interaction state-layer overlay (ADR-0009). */
.sd-date-range-picker__trigger::after {
  content: "";
  position: absolute;
  inset: 0;
  border-radius: inherit;
  corner-shape: inherit;
  background: transparent;
  pointer-events: none;
  transition: background-color var(--sd-duration-moderate) var(--sd-easing-standard);
}
.sd-date-range-picker__trigger[data-hovered]::after {
  background: var(--sd-state-hover);
}
.sd-date-range-picker__trigger[data-pressed]::after {
  background: var(--sd-state-pressed);
}

.sd-date-range-picker__trigger[data-focus-visible] {
  box-shadow: 0 0 0 var(--sd-state-focus-ring-width) color-mix(in srgb, var(--sd-state-focus-ring) calc(var(--sd-state-focus-ring-opacity) * 100%), transparent);
  outline: var(--sd-state-focus-ring-width) solid transparent;
}

.sd-date-range-picker__trigger[data-disabled] {
  opacity: var(--sd-state-disabled);
  cursor: not-allowed;
}

.sd-date-range-picker__description {
  padding-inline: var(--sd-date-range-picker-text-padding-inline);
  color: var(--sd-date-range-picker-description-foreground);
}

.sd-date-range-picker__error {
  padding-inline: var(--sd-date-range-picker-text-padding-inline);
  color: var(--sd-date-range-picker-error-foreground);
}
